mapper.select:
SELECT srr.id, srrd.id AS receiveDetailId, srr.source_id AS sourceId, srrd.source_detail_id AS sourceDetailId, srr.code, srr.source_code AS sourceCode, srr.so_code AS soCode, srr.customer_id AS customerId, srr.customer_name AS customerName, srr.inventory_org_id AS inventoryOrgId, srr.inventory_org_name AS inventoryOrgName, srr.approve_status AS approveStatus, srr.invalid_status AS invalidStatus, srrd.sku_id AS skuId, srrd.sku_no AS skuNo, srrd.return_type_dict AS returnTypeDict, srrd.return_qty AS returnQty, srrd.receive_qty AS receiveQty, srr.seller_name AS sellerName, srr.return_date AS returnDate, srr.bill_date AS billDate, srr.approve_user_name AS approveUserName, srr.create_user_name AS createUserName, srr.create_time AS createTime, srr.warehouse_id AS warehouseId FROM so_return_receive_detail srrd INNER JOIN so_return_receive srr ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE WHERE ${params.sqlMap.default} and srr.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
srr.create_time desc

select
count(distinct srr.id)
FROM so_return_receive_detail srrd
INNER JOIN so_return_receive srr ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE
WHERE srr.is_deleted = FALSE

    and srr.approve_status in

        #{item}



    and srr.bill_date >= #{params.billDateList[0]} and  (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > srr.bill_date


    and srr.invalid_status = #{params.invalidStatus}


    ${params.permissionSql}

SELECT srr.id, srrd.id AS receiveDetailId, srr.source_id AS sourceId, srrd.source_detail_id AS sourceDetailId, srr.code, srr.source_code AS sourceCode, srr.customer_id AS customerId, srr.customer_name AS customer_Name, srr.inventory_org_id AS inventoryOrgId, srr.inventory_org_name AS inventoryOrgName, srr.approve_status AS approveStatus, srr.invalid_status AS invalidStatus, srrd.sku_id AS skuId, srrd.sku_no AS skuNo, srrd.return_type_dict AS returnTypeDict, srrd.return_qty AS returnQty, srrd.receive_qty AS receiveQty, srr.seller_name AS sellerName, srr.return_date AS returnDate, srr.bill_date AS billDate, srr.approve_user_name AS approveUserName, srr.create_user_name AS createUserName, srr.create_time AS createTime FROM so_return_receive_detail srrd INNER JOIN so_return_receive srr ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE WHERE ${params.sqlMap.default} and srr.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
srr.create_time desc

SELECT srrd.id, srr.approve_status, srrd.main_id, srr.code, srr.source_id, srrd.source_detail_id, srr.customer_id, srr.customer_name, srr.sales_org_id, srr.sales_org_name, srr.seller_id, srr.seller_name, srr.sales_dept_id, srr.sales_dept_name, srr.warehouse_id, srr.warehouse_name, srr.type, srrd.sku_id, srrd.sku_no, srrd.return_qty, srrd.receive_qty, srrd.return_type_dict, srrd.return_reason_dict, srrd.remark FROM so_return_receive srr INNER JOIN so_return_receive_detail srrd ON srr.id = srrd.main_id AND srr.is_deleted=FALSE WHERE srrd.is_deleted=FALSE
and srr.id in
#{item}

SELECT DISTINCT srr.id, srr.code, srr.approve_status, srr.seller_name, srr.warehouse_name, srr.approve_status, srr.create_time FROM so_return_receive srr INNER JOIN so_return_receive_detail srrd ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE WHERE srr.is_deleted = FALSE AND srr.invalid_status = FALSE
and srr.approve_status in
#{item}
and srr.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > srr.bill_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY srr.create_time desc
